scription'],'sort_order'=>(int)$item['sort_order'],'active'=>(bool)$item['active']],JSON_UNESCAPED_UNICODE))?>'>Edit</button><form method="post" class="delete-form" data-name="<?=e($item['name'])?>"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($item['id'])?>"><button type="submit" class="danger">Hapus</button></form></div></td></tr><?php endforeach?><?php if(!$subServices):?><tr><td colspan="5">Belum ada sublayanan.</td></tr><?php endif?></tbody></table></div></section></div>
